insert into public.faqs (id, question, question_ar, answer, answer_ar, category, corridor_id, service_id, sort_order, is_active) values
  ('44444444-4444-4444-8444-000000000001', 'What is Hawwely?', 'إيه هو حوّلي؟', 'Hawwely is a free comparison platform that helps Egyptian expats find the cheapest way to send money home to Egypt. We compare exchange rates and fees across 10+ services in real-time.', 'حوّلي هو منصة مقارنة مجانية بتساعد المصريين بالخارج يلاقوا أرخص طريقة يبعتوا فلوس لمصر. بنقارن أسعار الصرف والعمولات في أكتر من 10 خدمات في الوقت الفعلي.', 'general', NULL, NULL, 1, true),
  ('44444444-4444-4444-8444-000000000002', 'Is Hawwely free?', 'حوّلي ببلاش؟', 'Yes, Hawwely is 100% free to use. We earn a small commission from some services when you use our links, at no extra cost to you.', 'أيوه، حوّلي مجاني 100%. بنكسب عمولة صغيرة من بعض الخدمات لما تستخدم لينكاتنا، من غير أي تكلفة إضافية عليك.', 'general', NULL, NULL, 2, true),
  ('44444444-4444-4444-8444-000000000003', 'How do you get your rates?', 'بتجيبوا الأسعار منين؟', 'We pull rates from official APIs, public websites, and our community of reporters who verify rates daily.', 'بنجيب الأسعار من APIs رسمية، مواقع عامة، ومجتمعنا من المتطوعين اللي بيتأكدوا من الأسعار كل يوم.', 'rates', NULL, NULL, 3, true),
  ('44444444-4444-4444-8444-000000000004', 'How often are rates updated?', 'الأسعار بتتحدث كل قد إيه؟', 'Exchange rates are updated every 30 minutes. Fee structures are verified daily.', 'أسعار الصرف بتتحدث كل 30 دقيقة. العمولات بنتأكد منها يومياً.', 'rates', NULL, NULL, 4, true),
  ('44444444-4444-4444-8444-000000000005', 'What is the mid-market rate?', 'إيه هو سعر السوق الحقيقي؟', 'The mid-market rate is the real exchange rate you see on Google or Reuters. It is the midpoint between buy and sell prices. Most transfer services add a markup on top of this rate, which is a hidden fee.', 'سعر السوق الحقيقي هو سعر الصرف الحقيقي اللي بتشوفه على جوجل. معظم خدمات التحويل بتضيف هامش على السعر ده، وده بيكون عمولة مخفية.', 'rates', NULL, NULL, 5, true),
  ('44444444-4444-4444-8444-000000000006', 'Which service is cheapest for Saudi Arabia to Egypt?', 'إيه أرخص طريقة تحويل من السعودية لمصر؟', 'It depends on the amount and speed you need. Generally, Wise offers the closest to mid-market rate, but for cash pickup, Tahweel Al Rajhi can be competitive. Use our comparison tool to check real-time rates.', 'بيعتمد على المبلغ والسرعة. عموماً، Wise بتقدم أقرب سعر لسعر السوق، لكن للاستلام كاش، تحويل الراجحي ممكن يكون أحسن. استخدم أداة المقارنة عندنا.', 'services', '22222222-2222-4222-8222-000000000001', NULL, 6, true),
  ('44444444-4444-4444-8444-000000000007', 'Does Hawwely transfer money itself?', 'حوّلي بيحوّل الفلوس بنفسه؟', 'No. Hawwely never touches your money. We are an independent comparison site — when you choose a service, you complete the transfer on that provider’s own website or app.', 'لأ. حوّلي عمره ما بيلمس فلوسك. إحنا موقع مقارنة مستقل — لما تختار خدمة، بتكمل التحويل على موقع أو تطبيق الخدمة نفسها.', 'security', NULL, NULL, 7, true),
  ('44444444-4444-4444-8444-000000000008', 'Is it safe to use the services listed on Hawwely?', 'الخدمات اللي على حوّلي آمنة؟', 'We only list licensed providers regulated by authorities such as the UK FCA, SAMA, the UAE Central Bank and the Central Bank of Egypt. Always double-check recipient details before you send.', 'بنعرض بس خدمات مرخصة وخاضعة لجهات رقابية زي FCA البريطانية، ساما، مصرف الإمارات المركزي، والبنك المركزي المصري. دايماً راجع بيانات المستلم قبل ما تبعت.', 'security', NULL, NULL, 8, true),
  ('44444444-4444-4444-8444-000000000009', 'What is the difference between the visible fee and the hidden fee?', 'إيه الفرق بين العمولة الظاهرة والعمولة المخفية؟', 'The visible fee is the fixed or percentage fee the service shows you. The hidden fee is the difference between the mid-market rate and the rate they give you, multiplied by your amount. Hawwely shows you both so you see the true cost.', 'العمولة الظاهرة هي الرسوم الثابتة أو النسبية اللي الخدمة بتقولك عليها. العمولة المخفية هي الفرق بين سعر السوق الحقيقي والسعر اللي بيدهولك، مضروب في المبلغ. حوّلي بيوريك الاتنين عشان تعرف التكلفة الحقيقية.', 'rates', NULL, NULL, 9, true),
  ('44444444-4444-4444-8444-000000000010', 'Can my family receive money on InstaPay?', 'أهلي يقدروا يستلموا على إنستاباي؟', 'Yes. Several services, including Wise and Paysend, can pay out to any Egyptian bank account, and your family can then move it instantly via InstaPay. Some providers deliver directly to InstaPay-linked accounts.', 'أيوه. خدمات كتير زي Wise وPaysend بتحوّل على أي حساب بنكي مصري، وأهلك يقدروا يحركوها فوراً عن طريق إنستاباي. وبعض الخدمات بتوصّل مباشرة لحسابات مربوطة بإنستاباي.', 'services', NULL, '11111111-1111-4111-8111-000000000012', 10, true),
  ('44444444-4444-4444-8444-000000000011', 'Which is the cheapest way to send money from the UAE to Egypt?', 'إيه أرخص طريقة تحويل من الإمارات لمصر؟', 'For bank deposits, Wise and Al Ansari Exchange usually offer the best AED to EGP rates. For cash pickup, compare Al Ansari with Remitly. Rates move during the day, so check the live comparison.', 'للتحويل على البنك، Wise والأنصاري للصرافة عادةً أحسن سعر درهم للجنيه. للاستلام كاش، قارن بين الأنصاري وريميتلي. السعر بيتحرك خلال اليوم، فاتأكد من المقارنة الحية.', 'services', '22222222-2222-4222-8222-000000000002', NULL, 11, true),
  ('44444444-4444-4444-8444-000000000012', 'How does Hawwely make money?', 'حوّلي بيكسب منين؟', 'Some providers pay us a referral commission when you sign up through our link. This never changes the rate you get, and it never changes our ranking — results are always sorted by the amount your family receives.', 'بعض الخدمات بتدفعلنا عمولة إحالة لما تسجّل من خلال لينكنا. ده عمره ما بيغيّر السعر اللي بتاخده، ولا بيغيّر ترتيب النتائج — النتائج دايماً مترتبة حسب المبلغ اللي أهلك هيستلموه.', 'general', NULL, NULL, 12, true),
  ('44444444-4444-4444-8444-000000000013', 'Why is the bank rate different from the rate on Google?', 'ليه سعر البنك مختلف عن السعر اللي على جوجل؟', 'Google shows the mid-market rate. Banks and transfer companies buy currency at a slightly better rate and sell it to you at a slightly worse one — that spread is how they profit.', 'جوجل بيعرض سعر السوق الحقيقي. البنوك وشركات التحويل بتشتري العملة بسعر أحسن شوية وتبيعهالك بسعر أوحش شوية — الفرق ده هو مكسبهم.', 'rates', NULL, NULL, 13, true),
  ('44444444-4444-4444-8444-000000000014', 'What is the best time of the month to send money to Egypt?', 'إيه أحسن وقت في الشهر أبعت فيه فلوس لمصر؟', 'There is no fixed best day, but rates tend to fluctuate around Central Bank announcements and month-end demand. Set a rate alert and we will notify you when the rate hits your target.', 'مفيش يوم ثابت، لكن الأسعار بتتحرك حوالين قرارات البنك المركزي وزحمة آخر الشهر. اعمل تنبيه سعر وهنبعتلك لما السعر يوصل للرقم اللي عايزه.', 'rates', NULL, NULL, 14, true)
insert into public.blog_posts (id, slug, title, title_ar, excerpt, excerpt_ar, content, content_ar, featured_image, category, tags, author_name, is_published, published_at, seo_title, seo_description, views, reading_minutes) values
  ('55555555-5555-4555-8555-000000000001', 'cheapest-way-to-send-money-from-saudi-to-egypt', 'The Cheapest Way to Send Money from Saudi Arabia to Egypt (2025 Guide)', 'أرخص طريقة لتحويل فلوس من السعودية لمصر (دليل 2025)', 'We compared Wise, Tahweel Al Rajhi, Western Union, Remitly and more for a 2,000 SAR transfer. The difference between the best and worst option was over 1,700 EGP.', 'قارنّا Wise وتحويل الراجحي وويسترن يونيون وريميتلي وغيرهم على تحويل 2,000 ريال. الفرق بين أحسن وأوحش خيار عدّى 1,700 جنيه.', '## Why the "best" option changes every month
insert into public.reviews (id, user_id, service_id, corridor_id, rating, title, title_ar, body, body_ar, amount_sent, amount_received, send_currency, receive_currency, reported_rate, transfer_speed_actual, would_recommend, author_name, is_verified, is_approved, helpful_count, created_at) values
  ('66666666-6666-4666-8666-000000000001', NULL, '11111111-1111-4111-8111-000000000001', '22222222-2222-4222-8222-000000000001', 5, 'Best rate I have found from Riyadh', 'أحسن سعر لقيته من الرياض', 'Sent 3,000 SAR to my mother in Mansoura. Arrived next morning in her CIB account, exact amount shown on Hawwely.', 'بعت 3,000 ريال لوالدتي في المنصورة. وصلت تاني يوم الصبح على حسابها في CIB، نفس الرقم اللي حوّلي عرضه بالظبط.', 3000, 39380, 'SAR', 'EGP', 13.21, '1 day', true, 'أحمد م.', true, true, 42, '2025-01-12T14:20:00.000Z'),
  ('66666666-6666-4666-8666-000000000002', NULL, '11111111-1111-4111-8111-000000000002', '22222222-2222-4222-8222-000000000002', 4, 'Fast cash pickup, rate drops after promo', 'كاش سريع، بس السعر بينزل بعد العرض', 'First transfer had a great promo rate. Second one was noticeably worse. Still the fastest for cash in Tanta.', 'أول تحويل كان سعره ممتاز بالعرض. التاني كان أوحش بشكل واضح. لسه أسرع حاجة للكاش في طنطا.', 1500, 19850, 'AED', 'EGP', 13.27, 'minutes', true, 'سارة ع.', true, true, 18, '2025-01-09T10:05:00.000Z'),
  ('66666666-6666-4666-8666-000000000003', NULL, '11111111-1111-4111-8111-000000000005', '22222222-2222-4222-8222-000000000001', 5, 'Al Rajhi is underrated', 'الراجحي أحسن مما الناس فاكرة', 'For 10,000 SAR the flat 15 SAR fee beats everything. Took about 4 hours to the NBE account.', 'لمبلغ 10,000 ريال العمولة الثابتة 15 ريال بتكسب كل حاجة. أخد حوالي 4 ساعات على حساب البنك الأهلي.', 10000, 130800, 'SAR', 'EGP', 13.1, 'hours', true, 'محمود س.', true, true, 61, '2025-01-07T18:40:00.000Z'),
  ('66666666-6666-4666-8666-000000000004', NULL, '11111111-1111-4111-8111-000000000003', '22222222-2222-4222-8222-000000000004', 3, 'Reliable but expensive', 'مضمون بس غالي', 'My father only trusts Western Union and picks up cash at the post office. It works, but I lose about 6% every time.', 'والدي مش بيثق غير في ويسترن يونيون وبيستلم كاش من البوسطة. شغالة، بس بخسر حوالي 6% كل مرة.', 500, 23100, 'USD', 'EGP', 46.5, 'minutes', false, 'كريم ه.', false, true, 27, '2025-01-03T09:15:00.000Z'),
  ('66666666-6666-4666-8666-000000000005', NULL, '11111111-1111-4111-8111-000000000009', '22222222-2222-4222-8222-000000000002', 5, 'Payday rate at Al Ansari was unbeatable', 'سعر الأنصاري أول الشهر ما يتغلبش', 'Branch in Deira had a promo rate on the 1st. Beat Wise by a small margin for 8,000 AED. Long queue though.', 'فرع ديرة كان عامل عرض يوم 1. كسب Wise بفرق بسيط على 8,000 درهم. بس الطابور كان طويل.', 8000, 107100, 'AED', 'EGP', 13.39, 'hours', true, 'هبة ر.', true, true, 35, '2025-01-02T16:30:00.000Z'),
  ('66666666-6666-4666-8666-000000000006', NULL, '11111111-1111-4111-8111-000000000006', '22222222-2222-4222-8222-000000000006', 4, 'Card to card in 10 minutes', 'من كارت لكارت في 10 دقايق', 'Used Paysend from London to my sister’s Meeza card. £1 fee, rate slightly below Wise but instant.', 'استخدمت باي سند من لندن لكارت ميزة بتاع أختي. عمولة جنيه إسترليني واحد، السعر أقل من Wise بشوية بس فوري.', 300, 18320, 'GBP', 'EGP', 61.1, 'minutes', true, 'يوسف ن.', true, true, 14, '2024-12-29T12:00:00.000Z'),
  ('66666666-6666-4666-8666-000000000007', NULL, '11111111-1111-4111-8111-000000000008', '22222222-2222-4222-8222-000000000004', 4, 'Zero fee but check the rate', 'بدون عمولة بس اتأكد من السعر', 'Sendwave is super easy from New Jersey. No fee, but the rate is about 2.5% under mid-market. Fine for small amounts.', 'سيندويف سهل جداً من نيو جيرسي. مفيش عمولة، بس السعر أقل من سعر السوق بحوالي 2.5%. كويس للمبالغ الصغيرة.', 200, 9640, 'USD', 'EGP', 48.2, 'minutes', true, 'مريم ف.', false, true, 9, '2024-12-22T20:10:00.000Z'),
  ('66666666-6666-4666-8666-000000000008', NULL, '11111111-1111-4111-8111-000000000001', '22222222-2222-4222-8222-000000000003', 5, 'KWD to EGP without the bank headache', 'دينار للجنيه من غير وجع دماغ البنك', 'Kuwaiti bank wanted 8 KWD in SWIFT fees. Wise charged about 1.2 KWD and gave the real rate. Two days to arrive.', 'البنك الكويتي كان عايز 8 دينار رسوم سويفت. Wise أخدت حوالي 1.2 دينار وإدتني السعر الحقيقي. وصلت في يومين.', 300, 48250, 'KWD', 'EGP', 161.5, '2 days', true, 'عمر ش.', true, true, 22, '2024-12-18T08:45:00.000Z')
